import { sharedAudio } from '../../core/Audio';
import type { MonsterKind } from './mission';
import { ENTITY_PROFILES, type SignalPoint } from './threat';

export const SHIP_AUDIO_VOICES = 8;
export type ShipSound =
  | 'door'
  | 'spark'
  | 'vent'
  | 'step'
  | 'pickup'
  | 'crew-step'
  | 'breath'
  /** Das Klacken, mit dem das Monster einen Raum absucht. */
  | 'klack'
  /** Die Ankündigung vor der Kabine. */
  | 'scream'
  /** Die aufgerissene Kabine. */
  | 'breach'
  /** Der eigene Herzschlag bei einer Verfolgung. */
  | 'heartbeat'
  /**
   * **Eine Lampe am Ende ihrer Zeit** — das Sirren und das Klacken, mit dem
   * sie ausgeht (`rules/lamps.ts`). Es hat einen Ort: Wer im Nebenraum steht,
   * hört, wo es gleich dunkel wird, und wer es hört, weiß auch, dass jemand
   * dort Licht gemacht hat.
   */
  | 'lamp';
export interface ShipAudioFrame {
  listener: SignalPoint;
  forward: SignalPoint;
  monster: SignalPoint | null;
  kind: MonsterKind;
  active: boolean;
  test: boolean;
  venting: boolean;
  machine?: SignalPoint;
  engineRepaired?: boolean;
  /** Metres per second of actual walking, excluding spectator flight. */
  playerSpeed?: number;
  /** In-game exertion 0..1; never microphone or breathing-tracker input. */
  exertion?: number;
  /**
   * Wie nah eine laufende Verfolgung ist (0…1) — daraus wird der Herzschlag.
   *
   * Er ist **kein** Geräusch der Welt, sondern eines im Kopf: Er sitzt am
   * Ohr des Zuhörers, wird schneller und lauter, je näher das Monster kommt,
   * und ist die einzige Auskunft, die man im Dunkeln über den Abstand hinter
   * sich bekommt. Spielwerte, nie eine gemessene Herzfrequenz.
   */
  chase?: number;
  /**
   * Das Hörmodell des Pakets Audio (`audio/hearing.ts`): effektive Entfernung
   * und Herkunft einer Quelle — um Ecken, durch Wände gedämpft. Fehlt es,
   * gilt die Luftlinie.
   */
  hearing?: (source: SignalPoint) => { distance: number; from: SignalPoint } | null;
  /** `false`, wenn ein anderer Mixer die Schritte des Monsters spielt (`audio/`). */
  footsteps?: boolean;
}
/** Länge, Abspielrate und Lautstärke je Geräusch — eine Tabelle statt einer Leiter aus Fragezeichen. */
const DURATIONS: Partial<Record<ShipSound, number>> = {
  door: 0.46,
  vent: 0.55,
  spark: 0.13,
  breath: 0.72,
  'crew-step': 0.12,
  klack: 0.11,
  scream: 0.95,
  breach: 0.52,
  heartbeat: 0.16,
  lamp: 0.34,
};
const RATES: Partial<Record<ShipSound, number>> = {
  door: 0.45,
  vent: 0.7,
  breath: 0.32,
  klack: 1.9,
  scream: 0.28,
  breach: 0.6,
  lamp: 2.4,
};
const VOLUMES: Partial<Record<ShipSound, number>> = {
  spark: 0.06,
  'crew-step': 0.038,
  breath: 0.045,
  klack: 0.055,
  scream: 0.19,
  breach: 0.16,
  heartbeat: 0.13,
  lamp: 0.07,
};

interface Voice {
  gain: GainNode;
  pan: StereoPannerNode;
  source: AudioScheduledSourceNode | null;
  envelope: GainNode | null;
  at: SignalPoint;
  volume: number;
}

/**
 * Head-relative stereo with inverse-square falloff; no HRTF convolution on mobile.
 * `heard` ersetzt die Luftlinie durch effektive Meter aus dem Hörmodell.
 */
export function spatialMix(
  listener: SignalPoint,
  forward: SignalPoint,
  source: SignalPoint,
  output: { pan: number; gain: number } = { pan: 0, gain: 0 },
  heard?: number,
): { pan: number; gain: number } {
  const dx = source.x - listener.x,
    dz = source.z - listener.z;
  const straight = Math.hypot(dx, dz),
    distance = heard ?? straight,
    length = Math.hypot(forward.x, forward.z);
  if (!Number.isFinite(distance) || !Number.isFinite(length)) {
    output.pan = 0;
    output.gain = 0;
    return output;
  }
  const pan =
    straight > 0.01 && length > 0.01 ? (dx * -forward.z + dz * forward.x) / (straight * length) : 0;
  output.pan = Math.min(1, Math.max(-1, pan));
  output.gain = distance > 28 ? 0 : 1 / (1 + (distance / 3.5) ** 2);
  return output;
}

/** Eight reusable stereo/envelope slots plus one machine oscillator, all synthesised locally. */
export class ShipAudio {
  private context: AudioContext | null = null;
  private readonly voices: Voice[] = [];
  private master: GainNode | null = null;
  private hum: { oscillator: OscillatorNode; gain: GainNode; pan: StereoPannerNode } | null = null;
  private noise: AudioBuffer | null = null;
  private listener: SignalPoint = { x: 0, z: 0 };
  private forward: SignalPoint = { x: 0, z: -1 };
  private readonly mix = { gain: 0, pan: 0 };
  private enabled = true;
  private disposed = false;
  private stepClock = 0;
  private playerStepClock = 0;
  private breathClock = 0;
  private heartClock = 0;
  private ventBefore = false;
  private pending: { kind: ShipSound; at: number; scale: number } | null = null;
  private hearing: ShipAudioFrame['hearing'] = undefined;

  get activeVoices(): number {
    let count = 0;
    for (const voice of this.voices) if (voice.source) count++;
    return count;
  }

  setEnabled(value: boolean): void {
    this.enabled = value;
    if (this.master && this.context)
      this.master.gain.setTargetAtTime(value ? 0.5 : 0, this.context.currentTime, 0.02);
  }

  update(dt: number, frame: ShipAudioFrame): void {
    if (this.disposed || !this.enabled || !this.ensure()) return;
    const ctx = this.context!;
    this.listener.x = frame.listener.x;
    this.listener.z = frame.listener.z;
    this.forward.x = frame.forward.x;
    this.forward.z = frame.forward.z;
    this.hearing = frame.hearing;
    for (const voice of this.voices)
      if (voice.source) {
        const mix = this.mixFor(voice.at);
        voice.pan.pan.setTargetAtTime(mix.pan, ctx.currentTime, 0.03);
        voice.gain.gain.setTargetAtTime(voice.volume * mix.gain, ctx.currentTime, 0.03);
      }
    if (this.hum) {
      const mix = this.mix;
      if (frame.machine) spatialMix(this.listener, this.forward, frame.machine, mix);
      else {
        mix.gain = 0;
        mix.pan = 0;
      }
      this.hum.gain.gain.setTargetAtTime(
        mix.gain * (frame.engineRepaired ? 0.012 : 0.025),
        ctx.currentTime,
        0.3,
      );
      this.hum.pan.pan.setTargetAtTime(mix.pan, ctx.currentTime, 0.1);
      this.hum.oscillator.frequency.setTargetAtTime(
        frame.engineRepaired ? 56 : 49,
        ctx.currentTime,
        0.3,
      );
    }
    const elapsed = Number.isFinite(dt) ? Math.max(0, Math.min(0.1, dt)) : 0;
    this.stepClock -= elapsed;
    this.playerStepClock -= elapsed;
    this.breathClock -= elapsed;
    const speed = Number.isFinite(frame.playerSpeed)
      ? Math.max(0, Math.min(8, frame.playerSpeed!))
      : 0;
    const exertion = Number.isFinite(frame.exertion)
      ? Math.max(0, Math.min(1, frame.exertion!))
      : 0;
    if (speed > 0.25 && this.playerStepClock <= 0) {
      this.playerStepClock = Math.max(0.28, 1.45 / speed);
      this.play('crew-step', this.listener);
    }
    if (exertion > 0.25 && this.breathClock <= 0) {
      this.breathClock = 2.5 - exertion * 1.2;
      this.play('breath', this.listener);
    }
    const chase = Number.isFinite(frame.chase) ? Math.max(0, Math.min(1, frame.chase!)) : 0;
    this.heartClock -= elapsed;
    if (chase > 0.05 && this.heartClock <= 0) {
      // Von einem Schlag je Sekunde herunter auf gut zwei — und der zweite
      // Schlag eines Paares kommt gleich hinterher, sonst klingt es wie ein
      // Klopfen und nicht wie ein Herz.
      this.heartClock = 1.05 - chase * 0.62;
      this.play('heartbeat', this.listener, frame.kind, 0.35 + chase * 0.65);
      this.pending = { kind: 'heartbeat', at: 0.17, scale: 0.22 + chase * 0.4 };
    }
    if (this.pending) {
      this.pending.at -= elapsed;
      if (this.pending.at <= 0) {
        this.play('heartbeat', this.listener, frame.kind, this.pending.scale);
        this.pending = null;
      }
    }
    const hostile = frame.active && !frame.test && frame.monster;
    if (hostile && frame.venting && !this.ventBefore) this.play('vent', frame.monster!, frame.kind);
    this.ventBefore = frame.venting;
    if (hostile && !frame.venting && frame.footsteps !== false && this.stepClock <= 0) {
      this.stepClock = ENTITY_PROFILES[frame.kind].cadence;
      this.play('step', frame.monster!, frame.kind);
    }
  }

  play(kind: ShipSound, at: SignalPoint, monster: MonsterKind = 'stalker', scale = 1): void {
    if (this.disposed || !this.enabled || !this.ensure()) return;
    const ctx = this.context!;
    let voice: Voice | undefined;
    for (const slot of this.voices)
      if (slot.source === null) {
        voice = slot;
        break;
      }
    const mix = this.mixFor(at);
    // Drop a distant or ninth simultaneous event; never let a spark burst allocate unbounded nodes.
    if (!voice || mix.gain < 0.015) return;
    const noisy =
      kind === 'spark' ||
      kind === 'vent' ||
      kind === 'door' ||
      kind === 'breath' ||
      kind === 'klack' ||
      kind === 'scream' ||
      kind === 'breach' ||
      kind === 'lamp' ||
      (kind === 'step' && monster === 'crawler');
    const duration = DURATIONS[kind] ?? 0.2;
    const source = noisy ? ctx.createBufferSource() : ctx.createOscillator();
    if ('buffer' in source) {
      source.buffer = this.noise;
      source.playbackRate.value = RATES[kind] ?? 1.2;
    } else {
      source.type = kind === 'pickup' ? 'sine' : monster === 'sentinel' ? 'triangle' : 'sine';
      const frequency =
        kind === 'pickup'
          ? 580
          : kind === 'crew-step'
            ? 105
            : kind === 'heartbeat'
              ? 58
              : ENTITY_PROFILES[monster].stepFrequency;
      source.frequency.setValueAtTime(frequency, ctx.currentTime);
      source.frequency.exponentialRampToValueAtTime(
        kind === 'pickup' ? 840 : frequency * 0.35,
        ctx.currentTime + duration,
      );
    }
    const envelope = ctx.createGain();
    envelope.gain.setValueAtTime(0.0001, ctx.currentTime);
    envelope.gain.exponentialRampToValueAtTime(
      1,
      ctx.currentTime + (kind === 'breath' ? 0.22 : 0.012),
    );
    envelope.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
    voice.source = source;
    voice.envelope = envelope;
    voice.at.x = at.x;
    voice.at.z = at.z;
    voice.volume =
      (kind === 'step' ? 0.14 * ENTITY_PROFILES[monster].sound : (VOLUMES[kind] ?? 0.08)) *
      Math.max(0, Math.min(2, scale));
    voice.gain.gain.setValueAtTime(voice.volume * mix.gain, ctx.currentTime);
    voice.pan.pan.setValueAtTime(mix.pan, ctx.currentTime);
    source.connect(envelope).connect(voice.gain);
    source.onended = () => {
      source.disconnect();
      envelope.disconnect();
      if (voice.source === source) {
        voice.source = null;
        voice.envelope = null;
      }
    };
    source.start();
    source.stop(ctx.currentTime + duration + 0.02);
  }

  /** Die Luftlinie — oder, mit Hörmodell, der Weg um die Ecke aus der letzten Tür. */
  private mixFor(at: SignalPoint): { pan: number; gain: number } {
    const heard = this.hearing?.(at);
    return spatialMix(this.listener, this.forward, heard?.from ?? at, this.mix, heard?.distance);
  }

  private ensure(): boolean {
    if (this.context) return this.context.state === 'running';
    const ctx = sharedAudio();
    if (!ctx || ctx.state !== 'running') return false;
    this.context = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.enabled ? 0.5 : 0;
    this.master.connect(ctx.destination);
    for (let i = 0; i < SHIP_AUDIO_VOICES; i++) {
      const gain = ctx.createGain(),
        pan = ctx.createStereoPanner();
      gain.connect(pan).connect(this.master);
      this.voices.push({ gain, pan, source: null, envelope: null, at: { x: 0, z: 0 }, volume: 0 });
    }
    this.noise = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
    const samples = this.noise.getChannelData(0);
    let seed = 71371,
      filtered = 0;
    for (let i = 0; i < samples.length; i++) {
      seed = (Math.imul(seed, 1664525) + 1013904223) | 0;
      filtered = filtered * 0.72 + (((seed >>> 0) / 0xffffffff) * 2 - 1) * 0.28;
      samples[i] = filtered;
    }
    const oscillator = ctx.createOscillator(),
      gain = ctx.createGain(),
      pan = ctx.createStereoPanner();
    oscillator.type = 'triangle';
    oscillator.frequency.value = 49;
    gain.gain.value = 0;
    oscillator.connect(gain).connect(pan).connect(this.master);
    oscillator.start();
    this.hum = { oscillator, gain, pan };
    return true;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    for (const voice of this.voices) {
      if (voice.source) {
        voice.source.stop();
        voice.source.disconnect();
      }
      voice.gain.disconnect();
      voice.pan.disconnect();
      voice.envelope?.disconnect();
    }
    this.voices.length = 0;
    this.hum?.oscillator.stop();
    this.hum?.oscillator.disconnect();
    this.hum?.gain.disconnect();
    this.hum?.pan.disconnect();
    this.hum = null;
    this.master?.disconnect();
    this.master = null;
    this.noise = null;
  }
}
